const e={meta:{title:"POP · SaaS-ul creatorilor UEFN"},nav:{features:"Funcționalități",pricing:"Prețuri",faq:"Întrebări",login:"Conectare",join:"Intră în beta",home:"POP, acasă",lang:"Limbă",search:"Caută o țară"},hero:{announce:"Beta privată deschisă creatorilor UEFN",h1a:"Creează în UEFN.",h1b:"Singur sau în echipă, fără haos.",subA:"POP este SaaS-ul care îi ajută pe creatorii UEFN de la idee la lansare: ",subB:"sarcini de o oră",subC:", Verse legat de UEFN, tablă albă, analiza pieței și împărțirea câștigurilor.",cta:"Intră pe lista de așteptare",see:"Vezi funcționalitățile",micro1:"Beta privată",micro2:"Acces pe lista de așteptare",micro3:"Legat de UEFN"},marquee:{label:"Funcționează cu instrumentele tale",epic:"API-ul Fortnite de la Epic"},pain:{eyebrow:"Problema",h2a:"Discord, Google Docs, Verse în .txt…",h2b:"iar harta nu avansează.",without:"Fără POP",with:"Cu POP",bad:["„Cine s-a atins de spawner?”","Verse-ul circulă pe Discord în .txt","O listă de sarcini într-un Google Doc","Tabelul câștigurilor, versiunea 7","„Deci când lansăm?”","Construim fără să știm dacă genul merge"],good:["Fiecare acțiune e înregistrată și reversibilă","Ctrl+S trimite Verse-ul în UEFN","Sarcini de o oră, cu dependențe","Un extras clar pentru fiecare","Etape și întârzieri urmărite automat","Un verdict pe gen, cu cifre reale"]},feat:{eyebrow:"Funcționalități",h2:"Tot ce trebuie ca să creezi în UEFN, de la idee la ziua lansării.",p:"Ce vezi aici sunt ecranele reale din POP, simplificate.",items:[{tag:"Sarcini și planificare",h:"Sarcini de o oră. O planificare care ține.",p:"Generatorul împarte harta în sarcini de o oră, cu dependențele lor. Planificarea urmărește etapele și semnalează întârzierile, iar un asistent integrat rezumă ziua.",pts:["Kanban și dependențe","Etape și întârzieri urmărite","Rezumatul zilei"]},{tag:"Editor Verse",h:"Ctrl+S și e deja în UEFN.",p:"Verse-ul se scrie în POP și ajunge direct în proiect: compilare, erori la linia corectă, sesiune de test. Asistentul explică și corectează, fără serviciu extern.",pts:["Compilare în UEFN","Erori la linie","Corecturi propuse"]},{tag:"Organizator",h:"Toate dispozitivele. Ordonate în trei secunde.",p:"Caută după tag, tip sau dosar, selectează douăzeci și redenumește, mută sau duplică dintr-odată. Ctrl+Z anulează. Dacă UEFN e închis, modificările așteaptă.",pts:["Căutare tag:, type:, dosar:","Modificări în masă","Totul e reversibil"]},{tag:"Tablă albă",h:"Desenați harta împreună.",p:"Notițe, forme, săgeți, culori, aldin, subliniat: tot ce trebuie pentru idei. Votați, apoi transformați cele mai bune notițe în sarcini.",pts:["Formatare completă","Colaborare în timp real","Notițe → sarcini"]},{tag:"Analiză",h:"Află ce să construiești înainte să construiești.",p:"Ce genuri atrag jucători, unde e loc liber, ce hărți decolează de la lansare și ce e în trend pe video. Cifre din API-ul oficial Epic.",pts:["Verdict pe gen","Hărți care merg","Trenduri TikTok și Shorts"]},{tag:"Plăți",h:"Fiecare știe cât câștigă.",p:"Reguli de împărțire procentuale, fixe sau pe sarcină, import de câștiguri, extras pe persoană. Gata cu tabelele pierdute pe Discord.",pts:["Procent, fix, pe sarcină","Import CSV","Extrasul fiecăruia"]}],aiB:"Folosești deja o IA?",aiText:"Conectează Claude, Cursor, Codex sau altă IA compatibilă MCP: preia o sarcină, scrie Verse-ul, compilează, apoi închide sarcina cu o notă. Fiecare acțiune e înregistrată și reversibilă."},stats:[["1 h","pe sarcină, ca să avansezi zilnic"],["0","servicii IA externe obligatorii"],["7 zile","de statistici pe hartă, din API-ul Epic"],["100%","din acțiunile UEFN reversibile"]],pricing:{eyebrow:"Prețuri",h2:"Alege-ți planul.",p:"POP e în beta privată: accesul se face pe lista de așteptare. Prețurile se aplică la lansare și vei fi anunțat înainte de orice plată.",perMonth:"/ lună",compare:"Compară planurile",unlimited:"Nelimitat",soon:"În curând",plans:[{name:"Creator",tag:"Pentru început",desc:"O hartă, o echipă mică, tot esențialul.",cta:"Intră pe listă"},{name:"Studio",tag:"Cel mai complet",desc:"Pentru studiourile care lansează hărți în echipă.",cta:"Intră pe listă"},{name:"Studio+",tag:"În curând",desc:"Tot din Studio, plus POP Forge: aplicația desktop care construiește în UEFN.",cta:"Intră pe listă"}],rows:["Organizare","Sarcini de o oră, Kanban, dependențe","Asistent integrat (rezumatul zilei, întârzieri)","Pagini, tablă albă, planificare și etape","Hărți","Membri","UEFN","UEFN Link: proiecte sincronizate","Editor Verse legat (compilare, erori la linie)","Organizator de actori și modificări în masă","IA conectate (Claude, Cursor, Codex…)","POP Forge: construcție asistată în UEFN","Creștere","Analiza pieței și hărți care merg","Trenduri video TikTok și YouTube Shorts","Schimb de playtesturi și ziua lansării","Împărțirea câștigurilor și extrase","Discord, GitHub, Lore"]},faq:{eyebrow:"Întrebări",h2:"Întrebările pe care le primim.",items:[["Am nevoie de un PC cu Windows?","Pentru a lega UEFN, da: UEFN rulează doar pe Windows, iar UEFN Link pornește pe acel PC. Restul POP merge în orice browser, inclusiv pe Mac."],["POP îmi publică harta?","Nu. POP pregătește totul (verificare înainte de publicare, playtesturi, planul zilei lansării), dar publicarea se face mereu în portalul de creatori Epic."],["Merge POP dacă lucrez singur?","Da. POP e făcut atât pentru creatorii care lucrează singuri, cât și pentru echipe: planul Creator e gratuit pentru o hartă și poți invita membri mai târziu fără să schimbi nimic."],["Și dacă vreau să folosesc IA mea?","Conectează Claude, Cursor, Codex sau altă IA compatibilă MCP în „IA conectate”. Poate citi și modifica sarcinile, Verse-ul și actorii UEFN, iar fiecare acțiune e înregistrată și reversibilă."],["De unde vin cifrele din analiză?","Din API-ul oficial Fortnite de la Epic: jucători, vârf de jucători simultani, timp de joc și retenție pentru fiecare hartă publică, pe 7 zile."],["Cum obțin acces?","POP e în beta privată. Intră pe lista de așteptare: verificăm cererile una câte una, apoi îți trimitem numele de utilizator și o parolă provizorie, pe care o schimbi la prima conectare."],["Cât costă?","Prețurile sunt afișate mai sus. Se aplică la deschiderea POP; membrii beta sunt anunțați înainte de orice plată."]]},final:{h2a:"Următoarea ta hartă",h2b:"începe aici.",p:"Intră pe lista de așteptare: îți trimitem accesul imediat ce se eliberează un loc."},foot:{made:"Făcut de creatori Fortnite, pentru creatori Fortnite.",legal:"Fortnite și UEFN sunt mărci comerciale ale Epic Games. POP nu este afiliat cu Epic Games și nici aprobat de aceasta.",product:"Produs",help:"Ajutor",account:"Cont"},mock:{overview:"Prezentare",nav:["Prezentare","Pagini","Tablă albă","Sarcini","Editor Verse","Organizator","Piață"],hello:"Bună, Léa, îți propun să începi cu #42.",late:"2 sarcini întârziate (cea mai veche era pe 12 nov.).",mile:"Etapa „Beta” în 5 zile: mai sunt 9 sarcini, întârziere estimată de 1 zi.",take:"Preia",start:"Începe",unlocks:"deblochează alte 3 sarcini",today:"termen azi",waits:"așteaptă #42",todo:"De făcut",doing:"În lucru",done:"Gata",tasks:["Sistem de scor","Decor zona 2","Ecran final","Playtest intern","Spawn jucători","Furtuna"],sent:"trimis în UEFN",err:"Linia 12: int și float nu se pot aduna.",fix:"Corectează: Points += 1",red:"Echipa roșie",selected:"2 selectate",rename:"Redenumește",move:"Mută",dup:"Duplică",s1:"Mod echipe 4v4",s2a:"Boss final",s2b:"în centru",s3:"Economie: 1 monedă / eliminare",verdicts:["Oportunitate bună","Popular, dar disputat","Saturat","Nișă"],typical:"jucători / hartă tipică",earnings:"Câștigurile din octombrie",roles:["Cod · 40%","Hartă · 35%","Muzică · fix","Rest"],noTransfer:"POP calculează, nu face niciun transfer."},wl:{eyebrow:"Beta privată",title:"Intră pe lista de așteptare",intro:"Deschidem POP treptat, ca să fim alături de fiecare creator. Spune-ne cine ești și îți trimitem accesul cât mai repede.",pageIntro:"În timpul beta, conturile POP sunt create de echipă. Spune-ne cine ești: după ce accesul e aprobat, primești numele de utilizator și o parolă provizorie.",invalid:"Acest link de acces e invalid, deja folosit sau expirat. Trimite o nouă cerere sau scrie echipei POP.",name:"Nume sau pseudonim",email:"E-mail",studio:"Studio",optional:"(opțional)",studioPh:"Numele studioului",team:"Mărimea echipei",teams:["Singur","2–3","4–10","Peste 10"],exp:"Experiență",exps:["Începător în UEFN","Câteva hărți publicate","Creator experimentat","Studio profesionist"],links:"Hărțile sau rețelele tale",linksPh:"Coduri de insulă, TikTok, YouTube…",msg:"Ce vrei să faci cu POP",msgPh:"Ex.: suntem 4 pe o hartă tycoon și ne pierdem între Discord și Google Docs.",send:"Cere acces",sending:"Se trimite…",nospam:"Fără spam: îți scriem doar ca să-ți dăm accesul.",okTitle:"Am notat, mulțumim!",okText:"Cererea ta a ajuns la echipa POP. Imediat ce se eliberează un loc, îți trimitem numele de utilizator și o parolă provizorie.",alreadyTitle:"Ești deja pe listă.",approvedTitle:"Accesul tău e deja aprobat.",approvedText:"Contul tău e gata: echipa POP îți trimite numele de utilizator și parola provizorie. Dacă nu, scrie-ne.",close:"Închide"}};export{e as default};
